#[test]
fn asset_delivery_window_refuses_oversized_store_chunks() {
    let error = super::advance_asset_delivery_window(10, 4, 5)
        .expect_err("an oversized store chunk must not wrap remaining");
    assert_eq!(error.kind(), std::io::ErrorKind::InvalidData);
    assert_eq!(
        super::advance_asset_delivery_window(10, 4, 4).expect("exact window"),
        (14, 0)
    );
}

#[test]
fn asset_signed_url_request_accepts_empty_defaults_and_types_parse_refusals() {
    let empty = super::parse_asset_signed_url_issue_request(Ok(Bytes::new()))
        .expect("empty issuance body is the default request");
    let omitted = super::parse_asset_signed_url_issue_request(Ok(Bytes::from_static(b"{}")))
        .expect("omitted variant is valid");
    assert_eq!(empty, omitted);
    assert_eq!(empty.variant, None);
    assert_eq!(empty.ttl_ms, None);
    assert_eq!(empty.width_px, None);

    let malformed = super::parse_asset_signed_url_issue_request(Ok(Bytes::from_static(
        br#"{"ttlMs":"forever"}"#,
    )))
    .expect_err("a malformed field refuses through the typed asset diagnostic");
    assert_eq!(
        malformed.0.diagnostic.code,
        "SNAPBACK_ASSET_REQUEST_INVALID"
    );
    assert_eq!(malformed.0.diagnostic.details["field"], "ttlMs");
    assert_eq!(
        malformed.into_response().status(),
        StatusCode::BAD_REQUEST,
        "malformed issuance never escapes as a framework 422"
    );

    let invalid_json = super::parse_asset_signed_url_issue_request(Ok(Bytes::from_static(b"{")))
        .expect_err("invalid JSON refuses through the same typed diagnostic");
    assert_eq!(
        invalid_json.0.diagnostic.code,
        "SNAPBACK_ASSET_REQUEST_INVALID"
    );
    assert_eq!(invalid_json.0.diagnostic.details["field"], "body");
    assert_eq!(
        invalid_json.into_response().status(),
        StatusCode::BAD_REQUEST
    );

    let unknown = super::parse_asset_signed_url_issue_request(Ok(Bytes::from_static(
        br#"{"surprise":true}"#,
    )))
    .expect_err("an unknown field refuses through the typed diagnostic");
    assert_eq!(unknown.0.diagnostic.details["field"], "surprise");
    assert_eq!(unknown.into_response().status(), StatusCode::BAD_REQUEST);

    let trailing = super::parse_asset_signed_url_issue_request(Ok(Bytes::from_static(b"{} {}")))
        .expect_err("trailing JSON refuses through the typed diagnostic");
    assert_eq!(trailing.0.diagnostic.details["field"], "body");
    assert_eq!(trailing.into_response().status(), StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn asset_signed_url_route_empty_and_omitted_body_issue_primary() {
    let mut snapback = crate::local::tests::asset_profile_snapback();
    let asset_id = crate::local::tests::asset_ready_under_intent(
        &mut snapback,
        "user_a",
        b"signed-route-defaults",
        "signedUpload",
    );
    let authority =
        crate::local::tests::asset_dev_authority(&snapback, "user_a", InvocationSource::HttpQuery);
    let state = Arc::new(Mutex::new(snapback));

    for body in [Bytes::new(), Bytes::from_static(b"{}")] {
        let issued = super::asset_signed_url_issue_route(
            State(state.clone()),
            Extension(authority.clone()),
            AxumPath(asset_id.clone()),
            Ok(body),
        )
        .await
        .expect("empty/default issuance succeeds");
        assert_eq!(issued.0.variant, "primary");
        assert!(
            issued
                .0
                .url
                .contains(&format!("/{asset_id}/primary?token="))
        );
        assert_eq!(issued.into_response().status(), StatusCode::OK);
    }
}

#[tokio::test]
async fn network_profile_http_release_marks_delay_and_keeps_normal_identity() {
    let profiles = crate::network_profile::NetworkProfileState::new();
    let authority = crate::network_profile::NetworkProfileAuthority::classified(
        crate::contract_types::ServerProfile::Test,
        crate::auth::deployment::AuthDeploymentTarget::Local,
        false,
        false,
    );
    profiles
        .activate(
            crate::network_profile::NetworkConditionProfile {
                name: "test-delay".to_owned(),
                mutation_ack_delay_ms: 30,
                live_delta_delay_ms: 30,
                query_response_delay_ms: 30,
                jitter_ms: 0,
            },
            authority,
            crate::network_profile::NetworkProfileSource::Api,
            None,
        )
        .unwrap();

    let ready_at = Instant::now();
    let rejected = super::prepare_mutation_network_egress(
        &profiles,
        crate::network_profile::MutationEgressBasis::ResultReady,
        ready_at,
    )
    .expect("a rejected mutation uses its result-readiness deadline");
    assert!(rejected.release_at() >= ready_at + std::time::Duration::from_millis(30));
    let started = Instant::now();
    let delayed = super::release_network_profiled_response(
        axum::response::Response::new(axum::body::Body::empty()),
        Some(rejected),
    )
    .await;
    assert!(started.elapsed() >= std::time::Duration::from_millis(20));
    assert!(started.elapsed() < std::time::Duration::from_secs(1));
    assert_eq!(
        delayed
            .headers()
            .get(crate::network_profile::NETWORK_PROFILE_HEADER)
            .and_then(|value| value.to_str().ok()),
        Some("test-delay")
    );
    assert_eq!(
        delayed
            .extensions()
            .get::<super::NetworkProfileObservation>()
            .map(|observation| observation.0.profile.name.as_str()),
        Some("test-delay")
    );

    profiles
        .activate(
            crate::network_profile::NetworkConditionProfile::normal(),
            authority,
            crate::network_profile::NetworkProfileSource::Api,
            None,
        )
        .unwrap();
    let started = Instant::now();
    let normal = super::release_network_profiled_response(
        axum::response::Response::new(axum::body::Body::empty()),
        profiles.admit_result(
            crate::network_profile::NetworkEgressLane::QueryResponse,
            Instant::now(),
        ),
    )
    .await;
    assert!(started.elapsed() < std::time::Duration::from_secs(1));
    assert!(
        normal
            .headers()
            .get(crate::network_profile::NETWORK_PROFILE_HEADER)
            .is_none()
    );
}

#[tokio::test]
async fn poll_lane_marker_uses_frame_admission_snapshot_and_normal_preserves_bytes() {
    let mut context = ServerContext::detached();
    context.profile = ServerProfile::Test;
    let state = test_app_state_from_snapback(
        LocalSnapback::memory().expect("poll marker fixture"),
        context,
    );
    let opened = state
        .connections
        .open(Some("profiled-poll".to_owned()), None, true)
        .expect("open poll grant");
    let prepare_act = || {
        state
            .connections
            .prepare_act(
                &opened.connection_id,
                Some(&opened.connection_token),
                None,
                true,
                super::now_millis(),
                Instant::now(),
            )
            .expect("prepare poll act")
    };
    let live_bytes = serde_json::to_vec(&crate::live_wire::LiveEnvelope::LiveReplace {
        network_profile: None,
        subscription_id: "sub_poll".to_owned(),
        function: "listTodos".to_owned(),
        version: 1,
        rows: vec![],
        resume: None,
    })
    .unwrap();
    state
        .activate_network_profile(
            crate::network_profile::NetworkConditionProfile {
                name: "poll-admission".to_owned(),
                mutation_ack_delay_ms: 0,
                live_delta_delay_ms: 1,
                query_response_delay_ms: 0,
                jitter_ms: 0,
            },
            crate::network_profile::NetworkProfileSource::Api,
            None,
        )
        .unwrap();
    let admission = state
        .network_profiles
        .admit_result(
            crate::network_profile::NetworkEgressLane::LiveDelta,
            Instant::now() - Duration::from_millis(1),
        )
        .expect("profiled frame captures admission snapshot");
    state
        .ephemeral
        .enqueue_durable_with_network_egress_for_test(
            &opened.connection_id,
            live_bytes.clone(),
            admission,
        );
    state
        .activate_network_profile(
            crate::network_profile::NetworkConditionProfile::normal(),
            crate::network_profile::NetworkProfileSource::Api,
            None,
        )
        .unwrap();

    let response = leased_queued_outbox_http_response(&state, prepare_act());
    let batch: Value = serde_json::from_slice(
        &to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("profiled poll body"),
    )
    .unwrap();
    let marked = batch[0]["Durable"]["payload"]
        .as_array()
        .unwrap()
        .iter()
        .map(|byte| byte.as_u64().unwrap() as u8)
        .collect::<Vec<_>>();
    let marked: Value = serde_json::from_slice(&marked).unwrap();
    assert_eq!(marked["network_profile"], "poll-admission");

    state
        .ephemeral
        .enqueue_durable_for_test(&opened.connection_id, live_bytes.clone());
    let response = leased_queued_outbox_http_response(&state, prepare_act());
    let normal_body = to_bytes(response.into_body(), usize::MAX)
        .await
        .expect("normal poll body");
    let expected_body = serde_json::to_vec(&vec![RealtimeEnvelope::Durable(
        crate::ephemeral::DurableMessage::new(live_bytes.clone()),
    )])
    .unwrap();
    assert_eq!(
        normal_body.as_ref(),
        expected_body,
        "normal poll batch stays byte-identical"
    );
    let batch: Value = serde_json::from_slice(&normal_body).unwrap();
    let normal = batch[0]["Durable"]["payload"]
        .as_array()
        .unwrap()
        .iter()
        .map(|byte| byte.as_u64().unwrap() as u8)
        .collect::<Vec<_>>();
    assert_eq!(
        normal, live_bytes,
        "normal poll payload stays byte-identical"
    );
}

#[tokio::test]
async fn network_profile_admin_api_uses_shared_authorizer_and_activation_gate() {
    let mut context = ServerContext::detached();
    context.profile = ServerProfile::Test;
    context.admin_token = Some("network-profile-admin".to_owned());
    let state = test_app_state_from_snapback(
        LocalSnapback::memory().expect("network profile admin fixture"),
        context,
    );
    let router = app(state.clone());
    let put = router
        .clone()
        .oneshot(
            Request::builder()
                .method("PUT")
                .uri("/_snapback/api/debug/network-profile")
                .header(header::CONTENT_TYPE, "application/json")
                .header("x-snapback-admin-token", "network-profile-admin")
                .body(Body::from(r#""optimistic""#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(put.status(), StatusCode::OK);
    assert_eq!(response_json(put).await["profile"]["name"], "optimistic");

    let get = router
        .clone()
        .oneshot(
            Request::builder()
                .method("GET")
                .uri("/_snapback/api/debug/network-profile")
                .header("x-snapback-admin-token", "network-profile-admin")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(get.status(), StatusCode::OK);
    let get = response_json(get).await;
    assert_eq!(get["profile"]["name"], "optimistic");
    assert_eq!(get["provenance"]["source"], "api");

    let console = router
        .clone()
        .oneshot(
            Request::builder()
                .method("PUT")
                .uri("/_snapback/api/debug/network-profile")
                .header(header::CONTENT_TYPE, "application/json")
                .header("x-snapback-admin-token", "network-profile-admin")
                .header(
                    crate::network_profile::NETWORK_PROFILE_SOURCE_HEADER,
                    "console",
                )
                .body(Body::from(r#""normal""#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(console.status(), StatusCode::OK);
    let console = response_json(console).await;
    assert_eq!(console["provenance"]["source"], "console");
    assert!(console["provenance"].get("principal").is_none());

    let mut context = ServerContext::detached();
    context.profile = ServerProfile::Prod;
    context.admin_token = Some("prod-admin".to_owned());
    let prod = test_app_state_from_snapback(
        LocalSnapback::memory().expect("production gate fixture"),
        context,
    );
    let forbidden = app(prod)
        .oneshot(
            Request::builder()
                .method("PUT")
                .uri("/_snapback/api/debug/network-profile")
                .header(header::CONTENT_TYPE, "application/json")
                .header("x-snapback-admin-token", "prod-admin")
                .body(Body::from(r#""optimistic""#))
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(forbidden.status(), StatusCode::FORBIDDEN);
    assert_eq!(
        response_json(forbidden).await["diagnostic"]["code"],
        crate::network_profile::NETWORK_PROFILE_FORBIDDEN_CODE
    );
}
