fn operator_delete_server_fixture(profile: ServerProfile, derived: bool) -> AppState {
    let mut context = ServerContext::detached();
    context.profile = profile;
    context.admin_token = Some("operator-delete-admin".to_owned());
    let mut snapback = LocalSnapback::memory().expect("operator delete server fixture");
    snapback
        .register_ephemeral_collection(EphemeralCollection::local_cursor("boardCursors", "boardId"))
        .expect("register operator delete fixture collection");
    let mut state = test_app_state_from_snapback(snapback, context)
        .with_server_startup_nonce("operator-delete-startup")
        .expect("install deterministic startup nonce");
    if derived {
        state.derived_instance_identity = Some(crate::instance_fork::DerivedForkLineageV1 {
            format_version: 1,
            fork_id: "fork_operator_delete_test".to_owned(),
            parent_instance_id: "parent-test".to_owned(),
            app_id: "operator-delete-test".to_owned(),
            created_at_ms: 1,
            fork_point_version: 1,
            expires_at_ms: Some(u64::MAX),
            promotable: false,
        });
    }
    state
}

fn operator_delete_headers() -> HeaderMap {
    let mut headers = HeaderMap::new();
    headers.insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json"),
    );
    headers.insert(
        "x-snapback-admin-token",
        HeaderValue::from_static("operator-delete-admin"),
    );
    headers
}

/// @ref LLP 0184#c-administrator-ephemeral-entry-delete--add-now — the
/// HTTP receipt must call the operation an unevaluated operator bypass,
/// and the process nonce is an enforced server-side fence.
#[tokio::test]
async fn operator_delete_http_checks_startup_nonce_and_discloses_bypass() {
    let state = operator_delete_server_fixture(ServerProfile::Test, false);
    let now_ms = super::now_millis();
    let published = state
        .ephemeral
        .publish(
            PublishRequest {
                collection: "boardCursors".to_owned(),
                scope: Scope::from_pairs([("boardId", "board-1")]),
                connection_id: "owner".to_owned(),
                session_id: None,
                user_id: None,
                custom_key: None,
                value: b"cursor".to_vec(),
                ttl_ms: None,
                auth: crate::ephemeral::AuthContext::default(),
            },
            now_ms,
        )
        .expect("publish inspected entry");
    let request_body = |startup_nonce: &str| {
        serde_json::to_vec(&json!({
            "collection": published.room.collection.clone(),
            "scope": published.room.scope.clone(),
            "entryKey": published.key.0.clone(),
            "expectedScopeEpoch": published.scope_epoch,
            "expectedEntryGeneration": published.entry_version,
            "reason": "repair stuck presence",
            "startupNonce": startup_nonce,
        }))
        .unwrap()
    };

    let stale = super::operator_delete_ephemeral(
        State(state.clone()),
        operator_delete_headers(),
        Ok(Bytes::from(request_body("wrong-process"))),
    )
    .await
    .expect_err("stale process identity must refuse before deletion")
    .into_response();
    assert_eq!(stale.status(), StatusCode::CONFLICT);
    assert_eq!(
        response_json(stale).await["diagnostic"]["code"],
        "SNAPBACK_EPHEMERAL_OPERATOR_DELETE_STALE_STARTUP_NONCE"
    );

    let receipt = super::operator_delete_ephemeral(
        State(state),
        operator_delete_headers(),
        Ok(Bytes::from(request_body("operator-delete-startup"))),
    )
    .await
    .expect("matching process, epoch, and generation delete")
    .0;
    assert_eq!(receipt["operation"], "ephemeral.operatorDelete");
    assert_eq!(receipt["authorityMode"], "operatorBypass");
    assert_eq!(receipt["authorizationEvaluated"], false);
    assert_eq!(receipt["bypass"], true);
    assert_eq!(receipt["ok"], true);
    assert!(
        receipt["note"]
            .as_str()
            .is_some_and(|note| note.contains("not an authorization decision"))
    );
}

#[tokio::test]
async fn operator_delete_refuses_production_and_derived_before_body_parsing() {
    for (state, expected_code) in [
        (
            operator_delete_server_fixture(ServerProfile::Prod, false),
            "SNAPBACK_EPHEMERAL_OPERATOR_DELETE_TARGET_REFUSED_HOSTED",
        ),
        (
            operator_delete_server_fixture(ServerProfile::Test, true),
            "SNAPBACK_EPHEMERAL_OPERATOR_DELETE_TARGET_REFUSED_DERIVED",
        ),
    ] {
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-snapback-admin-token",
            HeaderValue::from_static("operator-delete-admin"),
        );
        let response = super::operator_delete_ephemeral(State(state), headers, Ok(Bytes::new()))
            .await
            .expect_err("target posture must refuse malformed body without parsing it")
            .into_response();
        assert_eq!(response.status(), StatusCode::FORBIDDEN);
        assert_eq!(
            response_json(response).await["diagnostic"]["code"],
            expected_code
        );
    }
}

struct ManualServerAuthClock {
    base_epoch_ms: u64,
    epoch_ms: AtomicU64,
    monotonic_origin: Instant,
}

impl ManualServerAuthClock {
    fn new(epoch_ms: u64) -> Self {
        Self {
            base_epoch_ms: epoch_ms,
            epoch_ms: AtomicU64::new(epoch_ms),
            monotonic_origin: Instant::now(),
        }
    }

    fn set(&self, epoch_ms: u64) {
        self.epoch_ms.store(epoch_ms, Ordering::SeqCst);
    }

    fn monotonic_at(&self, epoch_ms: u64) -> Instant {
        self.monotonic_origin + Duration::from_millis(epoch_ms.saturating_sub(self.base_epoch_ms))
    }
}

#[test]
fn one_database_rejects_a_second_independent_app_state_graph() {
    let first = test_detached_app_state(LocalSnapback::memory().expect("shared registry fixture"));
    let clone = first.clone();
    assert!(
        first
            .service_authority_fences
            .is_same_registry(&clone.service_authority_fences),
        "router clones retain one terminal graph"
    );
    let second = AppState::try_new(
        first.snapback.clone(),
        first.read.clone(),
        first.ephemeral.clone(),
        (*first.server).clone(),
    );
    assert!(
        second.is_err(),
        "a second independent connection/lifecycle graph must be rejected"
    );
}

#[tokio::test]
async fn tus_upload_cors_headers_cover_the_protocol() {
    let state = test_app_state_from_snapback(
        LocalSnapback::memory().expect("TUS CORS fixture"),
        bound_loopback_context(),
    );
    let router = app(state);
    let preflight = |origin: &'static str| {
        Request::builder()
            .method("OPTIONS")
            .uri("/assets/tus/some-attempt-id")
            .header(header::ORIGIN, origin)
            .header(header::ACCESS_CONTROL_REQUEST_METHOD, "PATCH")
            .header(
                header::ACCESS_CONTROL_REQUEST_HEADERS,
                "tus-resumable,upload-offset,upload-checksum,content-type",
            )
            .body(Body::empty())
            .unwrap()
    };

    let allowed = router
        .clone()
        .oneshot(preflight("http://localhost:5173"))
        .await
        .unwrap();
    assert!(allowed.status().is_success());
    assert_eq!(
        allowed
            .headers()
            .get(header::ACCESS_CONTROL_ALLOW_ORIGIN)
            .and_then(|value| value.to_str().ok()),
        Some("http://localhost:5173")
    );
    let allow_headers = allowed
        .headers()
        .get(header::ACCESS_CONTROL_ALLOW_HEADERS)
        .and_then(|value| value.to_str().ok())
        .expect("preflight exposes the allowed request headers")
        .to_ascii_lowercase();
    for expected in [
        "tus-resumable",
        "upload-offset",
        "upload-length",
        "upload-checksum",
    ] {
        assert!(
            allow_headers
                .split(',')
                .any(|header_name| header_name.trim() == expected),
            "allow-headers omits {expected}: {allow_headers}"
        );
    }

    let head = router
        .clone()
        .oneshot(
            Request::builder()
                .method("HEAD")
                .uri("/assets/tus/some-attempt-id")
                .header(header::ORIGIN, "http://localhost:5173")
                .header("tus-resumable", crate::assets::ASSET_TUS_VERSION)
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    let expose_headers = head
        .headers()
        .get(header::ACCESS_CONTROL_EXPOSE_HEADERS)
        .and_then(|value| value.to_str().ok())
        .expect("TUS errors still expose the protocol response headers")
        .to_ascii_lowercase();
    for expected in [
        "upload-offset",
        "upload-length",
        "tus-resumable",
        "tus-version",
        "tus-extension",
        "tus-checksum-algorithm",
        "upload-expires-ms",
        "snapback-max-chunk-bytes",
    ] {
        assert!(
            expose_headers
                .split(',')
                .any(|header_name| header_name.trim() == expected),
            "expose-headers omits {expected}: {expose_headers}"
        );
    }

    let hostile = router
        .oneshot(preflight("http://attacker.invalid"))
        .await
        .unwrap();
    assert!(
        hostile
            .headers()
            .get(header::ACCESS_CONTROL_ALLOW_ORIGIN)
            .is_none(),
        "an unadmitted origin must not receive CORS admission"
    );
}

#[test]
fn tus_patch_route_runs_durable_append_between_writer_windows() {
    let source = include_str!("asset_routes.rs");
    let route = source
        .split("pub(super) async fn asset_tus_patch_route")
        .nth(1)
        .and_then(|tail| {
            tail.split("pub(super) async fn asset_tus_delete_route")
                .next()
        })
        .expect("asset TUS PATCH route source");
    let preflight = route
        .find("asset_tus_patch_preflight")
        .expect("lock-held TUS preflight");
    let blocking = route
        .find("tokio::task::spawn_blocking")
        .expect("blocking-pool staging append");
    let append = route.find("ticket.append").expect("durable staging append");
    let guard_return = route
        .find("(ticket, attempt_guard)")
        .expect("owned attempt guard returned from the blocking append");
    let commit = route
        .rfind("asset_tus_patch_commit")
        .expect("lock-held TUS offset CAS");
    assert!(
        preflight < blocking && blocking < append && append < guard_return && guard_return < commit,
        "write/flush/sync and its cancellation-safe guard must remain outside and between the two Local writer windows"
    );
    assert_eq!(
        route.matches("with_snapback(&state").count(),
        2,
        "the route has one preflight and one CAS writer window"
    );
}

#[tokio::test]
async fn http_telemetry_uses_registered_names_codes_and_private_unmatched_details() {
    let directory = tempfile::tempdir().expect("telemetry HTTP fixture directory");
    let database_path = directory.path().join("http-telemetry.sqlite3");
    let snapback = LocalSnapback::open(&database_path).expect("file-backed HTTP fixture");
    let state = test_app_state_from_snapback(snapback, bound_loopback_context());
    let telemetry = state.telemetry.clone();
    let router = app(state);

    let health = router
        .clone()
        .oneshot(
            Request::builder()
                .uri("/health")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(health.status(), StatusCode::OK);

    let options = router
        .clone()
        .oneshot(
            Request::builder()
                .method("OPTIONS")
                .uri("/health")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(options.status().is_success());

    let failed = router
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri("/auth/request-code")
                .header(header::CONTENT_TYPE, "application/json")
                .body(Body::from("{}"))
                .unwrap(),
        )
        .await
        .unwrap();
    assert!(!failed.status().is_success());

    let unmatched = router
        .oneshot(
            Request::builder()
                .uri("/attacker/path?secret=must-not-survive")
                .body(Body::empty())
                .unwrap(),
        )
        .await
        .unwrap();
    assert_eq!(unmatched.status(), StatusCode::NOT_FOUND);

    telemetry.force_flush().expect("flush HTTP observations");
    let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
        &database_path,
    ))
    .expect("open telemetry sibling");
    let health_count: i64 = raw
            .query_row(
                "SELECT COUNT(*) FROM telemetry_events WHERE kind='http_request' AND name='/health' AND phase='joined'",
                [],
                |row| row.get(0),
            )
            .unwrap();
    assert_eq!(
        health_count, 1,
        "the registered health operation is observed while inert OPTIONS is not"
    );
    let failure_code: Option<String> = raw
            .query_row(
                "SELECT code FROM telemetry_events WHERE kind='http_request' AND name='/auth/request-code' AND phase='joined' ORDER BY id DESC LIMIT 1",
                [],
                |row| row.get(0),
            )
            .expect("registered failure observation");
    assert!(
        failure_code
            .as_deref()
            .is_some_and(|code| code.starts_with("SNAPBACK_")),
        "the handler diagnostic code crosses the response seam: {failure_code:?}"
    );
    let unmatched_details: String = raw
            .query_row(
                "SELECT details FROM telemetry_events WHERE kind='http_request' AND name='_unmatched' AND phase='joined' ORDER BY id DESC LIMIT 1",
                [],
                |row| row.get(0),
            )
            .expect("unmatched observation");
    let unmatched_details: Value =
        serde_json::from_str(&unmatched_details).expect("unmatched details JSON");
    assert_eq!(unmatched_details["rawPath"], "/attacker/path");
    assert_eq!(unmatched_details["method"], "GET");
    assert!(!unmatched_details.to_string().contains("must-not-survive"));
}

#[test]
fn ws_connect_observation_joins_once_with_generic_disconnect_cause() {
    let directory = tempfile::tempdir().expect("socket telemetry fixture directory");
    let database_path = directory.path().join("socket-telemetry.sqlite3");
    let telemetry = crate::telemetry::Telemetry::open_for_database(
        &database_path,
        "01900000-0000-7000-8000-000000000001",
        crate::telemetry::TelemetryConfig::default(),
    )
    .expect("file-backed socket telemetry");

    {
        let observation = super::LiveSocketObservation::new(telemetry.start_span(
            "ws_connect",
            "/live/{connection_id}/stream",
            Some("socket-fixture"),
            None,
            true,
        ));
        telemetry.force_flush().expect("flush socket admission");
        let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
            &database_path,
        ))
        .expect("open socket telemetry sibling");
        let phases: Vec<String> = raw
            .prepare("SELECT phase FROM telemetry_events WHERE kind='ws_connect' ORDER BY id")
            .unwrap()
            .query_map([], |row| row.get(0))
            .unwrap()
            .collect::<Result<_, _>>()
            .unwrap();
        assert_eq!(phases, vec!["admission"]);
        observation.finish();
    }
    telemetry.force_flush().expect("flush socket terminal");

    let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
        &database_path,
    ))
    .expect("reopen socket telemetry sibling");
    let rows = raw
            .prepare(
                "SELECT phase,generation,correlation,details,recorded_ts_ms FROM telemetry_events WHERE kind='ws_connect' ORDER BY id",
            )
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<String>>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, i64>(4)?,
                ))
            })
            .unwrap()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
    assert_eq!(rows.len(), 2);
    assert_eq!(
        (rows[0].0.as_str(), rows[1].0.as_str()),
        ("admission", "terminal")
    );
    assert_eq!(rows[0].1, rows[1].1, "terminal keeps admitted generation");
    assert_eq!(rows[0].2.as_deref(), Some("socket-fixture"));
    assert_eq!(rows[1].2.as_deref(), Some("socket-fixture"));
    assert!(rows[1].4 > rows[0].4, "terminal is completion-bound");
    let details: Value =
        serde_json::from_str(rows[1].3.as_deref().expect("disconnect cause details")).unwrap();
    assert_eq!(details["cause"], "disconnected");
}

#[test]
fn ws_connect_observation_preserves_typed_terminal_code_and_reason() {
    let directory = tempfile::tempdir().expect("typed socket telemetry directory");
    let database_path = directory.path().join("typed-socket.sqlite3");
    let telemetry = crate::telemetry::Telemetry::open_for_database(
        &database_path,
        "01900000-0000-7000-8000-000000000001",
        crate::telemetry::TelemetryConfig::default(),
    )
    .expect("typed socket telemetry");
    {
        let observation = super::LiveSocketObservation::new(telemetry.start_span(
            "ws_connect",
            "/live/{connection_id}/stream",
            Some("typed-socket"),
            None,
            true,
        ));
        observation
            .terminal
            .record(crate::ephemeral::DeliveryTerminalEvent {
                code: crate::live_wire::LiveAuthErrorCode::SessionExpired,
                reason: crate::live_wire::LiveAuthErrorReason::Revoked,
                authority_disposition: crate::live_wire::LiveAuthorityDisposition::DurableDelete,
                close_by: Instant::now(),
            });
        observation.finish();
    }
    telemetry.force_flush().expect("flush typed terminal");
    let raw = rusqlite::Connection::open(crate::telemetry::Telemetry::path_for_database(
        &database_path,
    ))
    .expect("open typed socket telemetry");
    let (status, code, details): (i64, String, String) = raw
            .query_row(
                "SELECT status,code,details FROM telemetry_events WHERE kind='ws_connect' AND phase='terminal'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("typed socket terminal");
    assert_eq!(status, 500);
    assert_eq!(code, "SNAPBACK_AUTH_SESSION_EXPIRED");
    assert_eq!(
        serde_json::from_str::<Value>(&details).unwrap()["cause"],
        "revoked"
    );
}

